namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = "hist", Name = "History", Description = "Exploration of past events, civilizations, and cultural developments." },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = "cs101", Code = "CS 101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = "cs", IsFeatured = true,
                Instructor = new() { Name = "Dr. Alice Chen", Title = "Associate Professor", Email = "achen@university.edu", Bio = "Dr. Chen has 12 years of experience teaching introductory CS courses and has published research on CS pedagogy." }
            },
            new()
            {
                Id = "cs201", Code = "CS 201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = "cs", IsFeatured = false,
                Instructor = new() { Name = "Dr. Bob Martinez", Title = "Professor", Email = "bmartinez@university.edu", Bio = "Dr. Martinez specializes in algorithm optimization and has authored two widely adopted textbooks on data structures." }
            },
            new()
            {
                Id = "cs301", Code = "CS 301", Title = "Web Application Development",
                Description = "Design and build modern web applications using ASP.NET Core, Blazor, and cloud-based deployment. Covers front-end frameworks, RESTful APIs, and database integration.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = "cs", IsFeatured = true,
                Instructor = new() { Name = "Prof. Diana Okafor", Title = "Assistant Professor", Email = "dokafor@university.edu", Bio = "Prof. Okafor spent 8 years in industry as a full-stack developer before joining academia. She focuses on modern web technologies." }
            },
            new()
            {
                Id = "math101", Code = "MATH 101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = "math", IsFeatured = true,
                Instructor = new() { Name = "Dr. Elena Petrov", Title = "Professor", Email = "epetrov@university.edu", Bio = "Dr. Petrov is an award-winning educator with over 20 years of experience in mathematics instruction." }
            },
            new()
            {
                Id = "math201", Code = "MATH 201", Title = "Linear Algebra",
                Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and machine learning.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = "math", IsFeatured = false,
                Instructor = new() { Name = "Dr. Frank Liu", Title = "Associate Professor", Email = "fliu@university.edu", Bio = "Dr. Liu's research bridges pure mathematics and machine learning, with a focus on spectral methods." }
            },
            new()
            {
                Id = "eng101", Code = "ENG 101", Title = "College Writing",
                Description = "Develop effective academic writing skills through essay composition, peer review, and revision. Emphasis on argument, evidence, and clear prose.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = "eng", IsFeatured = false,
                Instructor = new() { Name = "Prof. Grace Kim", Title = "Senior Lecturer", Email = "gkim@university.edu", Bio = "Prof. Kim is a published author and writing coach who has taught composition at the university level for 15 years." }
            },
            new()
            {
                Id = "eng205", Code = "ENG 205", Title = "American Literature",
                Description = "Survey of American literary works from the colonial period to the present, examining themes of identity, freedom, and social change.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = "eng", IsFeatured = true,
                Instructor = new() { Name = "Dr. Henry Wallace", Title = "Professor", Email = "hwallace@university.edu", Bio = "Dr. Wallace is a leading scholar in 20th-century American fiction and has been a Fulbright Fellow." }
            },
            new()
            {
                Id = "phys101", Code = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions. Prerequisite: MATH 101 or equivalent.",
                Credits = 4, Schedule = "Mon/Wed 3:00–4:20 PM, Fri Lab 1:00–3:00 PM", DepartmentId = "phys", IsFeatured = false,
                Instructor = new() { Name = "Dr. Ines Ramirez", Title = "Associate Professor", Email = "iramirez@university.edu", Bio = "Dr. Ramirez is an experimental physicist whose research focuses on fluid dynamics and renewable energy." }
            },
            new()
            {
                Id = "hist101", Code = "HIST 101", Title = "World History to 1500",
                Description = "Survey of global civilizations from prehistory through the late medieval period, including Mesopotamia, Rome, China, and the Islamic world.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = "hist", IsFeatured = false,
                Instructor = new() { Name = "Dr. James Adeyemi", Title = "Professor", Email = "jadeyemi@university.edu", Bio = "Dr. Adeyemi is a historian of the ancient and medieval world with expertise in cross-cultural exchange along trade routes." }
            },
            new()
            {
                Id = "hist202", Code = "HIST 202", Title = "Modern European History",
                Description = "Europe from the Enlightenment to the present: revolutions, industrialization, world wars, and the formation of the European Union.",
                Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = "hist", IsFeatured = true,
                Instructor = new() { Name = "Dr. Karen Schmitt", Title = "Associate Professor", Email = "kschmitt@university.edu", Bio = "Dr. Schmitt specializes in modern German history and the politics of memory in post-war Europe." }
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(string departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, string? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

