@page "/"

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section mb-5">
    <h1>University Course Catalog</h1>
    <p class="lead">Explore departments, discover courses, and enroll for the upcoming semester.</p>
    <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <div class="row">
        @foreach (var course in featuredCourses)
        {
            var dept = Catalog.GetDepartment(course.DepartmentId);
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <span class="badge bg-secondary mb-2">@dept?.Name</span>
                        <h5 class="card-title">@course.Code — @course.Title</h5>
                        <p class="card-text text-muted">@course.Credits credits · @course.Schedule</p>
                        <p class="card-text">@Truncate(course.Description, 120)</p>
                    </div>
                    <div class="card-footer bg-transparent border-0">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    <div class="row">
        @foreach (var dept in departments)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text">@dept.Description</p>
                    </div>
                    <div class="card-footer bg-transparent border-0">
                        <a href="/courses?department=@dept.Id" class="btn btn-outline-secondary btn-sm">View Courses</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@page "/courses"
@rendermode InteractiveServer

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@inject NavigationManager Nav

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<div class="row mb-4">
    <div class="col-md-6 mb-2">
        <input type="text" class="form-control" placeholder="Search by title, code, or instructor…"
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4 mb-2">
        <select class="form-select" @bind="selectedDepartment">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 mb-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-hover">
            <thead class="table-light">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    var dept = Catalog.GetDepartment(course.DepartmentId);
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private string searchTerm = string.Empty;
    private string selectedDepartment = string.Empty;
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();

        var uri = Nav.ToAbsoluteUri(Nav.Uri);
        if (Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query).TryGetValue("department", out var deptValue))
        {
            selectedDepartment = deptValue.ToString();
        }

        UpdateResults();
    }

    private string SearchTerm
    {
        get => searchTerm;
        set { searchTerm = value; UpdateResults(); }
    }

    private string SelectedDepartment
    {
        get => selectedDepartment;
        set { selectedDepartment = value; UpdateResults(); }
    }

    private void UpdateResults()
    {
        filteredCourses = Catalog.SearchCourses(searchTerm, selectedDepartment);
    }

    private void ClearFilters()
    {
        searchTerm = string.Empty;
        selectedDepartment = string.Empty;
        UpdateResults();
    }
}

@page "/enroll"

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

<div class="row">
    <div class="col-lg-7">
        <div class="card">
            <div class="card-body">
                <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. You will receive a confirmation after submission.</p>

                <EditForm Model="request" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name</label>
                        <InputText id="fullName" class="form-control" @bind-Value="request.FullName" />
                        <ValidationMessage For="() => request.FullName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="request.StudentId" />
                        <ValidationMessage For="() => request.StudentId" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" class="form-select" @bind-Value="request.CourseId">
                            <option value="">— Select a course —</option>
                            @foreach (var course in courses)
                            {
                                <option value="@course.Id">@course.Code — @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => request.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                </EditForm>
            </div>
        </div>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest request { get; set; } = new();

    [SupplyParameterFromQuery]
    private string? courseId { get; set; }

    private List<Course> courses = new();

    protected override void OnInitialized()
    {
        courses = Catalog.GetAllCourses();

        if (!string.IsNullOrEmpty(courseId) && string.IsNullOrEmpty(request.CourseId))
        {
            request.CourseId = courseId;
        }
    }

    private void HandleSubmit()
    {
        // In a real app, this would persist the enrollment request
        submitted = true;
        submittedCourse = Catalog.GetCourse(request.CourseId);
        submittedName = request.FullName;
        submittedStudentId = request.StudentId;
    }

    private bool submitted;
    private Course? submittedCourse;
    private string submittedName = string.Empty;
    private string submittedStudentId = string.Empty;
}

