+{
+    <div class="alert alert-info">No courses match your search criteria.</div>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-hover">
+            <thead class="table-light">
+                <tr>
+                    <th>Code</th>
+                    <th>Title</th>
+                    <th>Department</th>
+                    <th>Credits</th>
+                    <th>Schedule</th>
+                    <th></th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var course in filteredCourses)
+                {
+                    var dept = Catalog.GetDepartment(course.DepartmentId);
+                    <tr>
+                        <td><strong>@course.Code</strong></td>
+                        <td>@course.Title</td>
+                        <td>@dept?.Name</td>
+                        <td>@course.Credits</td>
+                        <td>@course.Schedule</td>
+                        <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@code {
+    private string searchTerm = string.Empty;
+    private string selectedDepartment = string.Empty;
+    private List<Department> departments = new();
+    private List<Course> filteredCourses = new();
+
+    protected override void OnInitialized()
+    {
+        departments = Catalog.GetDepartments();
+
+        var uri = Nav.ToAbsoluteUri(Nav.Uri);
+        if (Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query).TryGetValue("department", out var deptValue))
+        {
+            selectedDepartment = deptValue.ToString();
+        }
+
+        UpdateResults();
+    }
+
+    private string SearchTerm
+    {
+        get => searchTerm;
+        set { searchTerm = value; UpdateResults(); }
+    }
+
+    private string SelectedDepartment
+    {
+        get => selectedDepartment;
+        set { selectedDepartment = value; UpdateResults(); }
+    }
+
+    private void UpdateResults()
+    {
+        filteredCourses = Catalog.SearchCourses(searchTerm, selectedDepartment);
+    }
+
+    private void ClearFilters()
+    {
+        searchTerm = string.Empty;
+        selectedDepartment = string.Empty;
+        UpdateResults();
+    }
+}
+

