@page "/enroll"

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

<div class="row">
    <div class="col-lg-7">
        <div class="card">
            <div class="card-body">
                <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. You will receive a confirmation after submission.</p>

                <EditForm Model="request" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name</label>
                        <InputText id="fullName" class="form-control" @bind-Value="request.FullName" />
                        <ValidationMessage For="() => request.FullName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="request.StudentId" />
                        <ValidationMessage For="() => request.StudentId" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" class="form-select" @bind-Value="request.CourseId">
                            <option value="">— Select a course —</option>
                            @foreach (var course in courses)
                            {
                                <option value="@course.Id">@course.Code — @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => request.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                </EditForm>
            </div>
        </div>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest request { get; set; } = new();

    [SupplyParameterFromQuery]
    private string? courseId { get; set; }

    private List<Course> courses = new();

    protected override void OnInitialized()
    {
        courses = Catalog.GetAllCourses();

        if (!string.IsNullOrEmpty(courseId) && string.IsNullOrEmpty(request.CourseId))
        {
            request.CourseId = courseId;
        }
    }

    private void HandleSubmit()
    {
        // In a real app, this would persist the enrollment request
        submitted = true;
        submittedCourse = Catalog.GetCourse(request.CourseId);
        submittedName = request.FullName;
        submittedStudentId = request.StudentId;
    }

    private bool submitted;
    private Course? submittedCourse;
    private string submittedName = string.Empty;
    private string submittedStudentId = string.Empty;
}

